//! The whole of `/etc` minus `capture.etc_exclude`, verbatim. Files over `capture.max_file` are listed
//! in the manifest but not copied (the engine decides that).

use std::path::Path;

use super::{Collector, Ctx, Output, Walk, walk_files};

pub(crate) struct Etc;

/// Regenerated by the system, never configuration.
const GENERATED: [&str; 3] = ["/etc/ld.so.cache", "/etc/adjtime", "/etc/.pwd.lock"];

impl Collector for Etc {
    fn name(&self) -> &'static str {
        "etc"
    }

    fn collect(&self, cx: &Ctx) -> Result<Output, String> {
        let mut skip_paths = cx.config.capture.etc_exclude.clone();
        skip_paths.extend(GENERATED.iter().map(ToString::to_string));
        let walk = Walk { prune_names: vec![".git".to_string()], skip_paths, ..Walk::default() };
        let mut out = Output::default();
        out.grab_all(walk_files(cx.host.as_ref(), Path::new("/etc"), &walk));
        Ok(out)
    }
}
